function sumarDias(iso, n) {
  const d = new Date(iso + 'T00:00');
  d.setDate(d.getDate() + n);
  return fechaIso(d);
}
function diasEntre(desde, hasta) {
  const ms = new Date(hasta + 'T00:00') - new Date(desde + 'T00:00');
  return Math.round(ms / 86_400_000);
